import polars as pl

def transform(raw: pl.DataFrame) -> pl.DataFrame:
    null_values = ["", "N/A", "n/a", "-", "null"]

    def clean_str(col: str) -> pl.Expr:
        return (
            pl.col(col)
            .str.strip_chars()
            .replace(null_values, None)
        )

    return raw.select(
        employee_id=clean_str("Employee ID").str.to_uppercase(),
        employee_name=clean_str("Employee Name"),
        work_date=clean_str("Work Date").str.to_date(format="%Y-%m-%d", strict=False),
        project_code=clean_str("Project Code").str.to_uppercase(),
        hours_normal=clean_str("Normal Hours").cast(pl.Float64, strict=False).round(2),
        hours_overtime=clean_str("Overtime Hours").cast(pl.Float64, strict=False).round(2),
    )
